import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test.describe("manage vendors", () => {
  test("a vendor under review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs }) => {
    // Arrange: a vendor in status "in_review", created and submitted by a member
    const member = await apiAs("member");
    const created = await expectStatus<{ id: string }>(
      await member.post("/api/vendors", {
        data: {
          name: uniqueName("VEN-09 Vendor"),
          category: "logistics",
          contact_email: "ops@ven09.example",
        },
      }),
      201,
    );
    const submitted = await expectStatus<{ id: string; status: string }>(
      await member.post(`/api/vendors/${created.id}/submit`),
      200,
    );
    expect(submitted.status).toBe("in_review");

    // Act: attempt to change the contact email
    const response = await member.patch(`/api/vendors/${created.id}`, {
      data: { contact_email: "billing@acmefreight.example" },
    });

    // Assert
    const body = await expectStatus<{ error: { code: string } }>(response, 409);
    expect(body.error.code).toBe("vendor_locked");
  });
});
